FOOTER="\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_"
def foot(b): return b if "Generated by [Claude Code]" in b else b.rstrip()+FOOTER
def strip_comment(s): return re.sub(r"<!--.*?-->\s*", "", s, count=1, flags=re.S).strip()
def read(p): return open(p, encoding="utf-8").read()
def title_body_titleline(s):
    m=re.search(r"^Title:\s*(.+)$", s, re.M); t=m.group(1).strip()
    body=s[m.end():]; return t, foot(strip_comment(body))
def cutadapt_issue(s):
    m=re.search(r"^\*\*Title:\*\*\s*(.+)$", s, re.M); t=m.group(1).strip()
    body=s[m.end():].strip(); return t, foot(body)
def scanpy_issue(s):
    t=re.search(r"^# Bug report:\s*(.+)$", s, re.M).group(1).strip()
    desc=re.search(r"\*\*What happened\?\*\*\s*(.*?)\*\*Minimal code sample\*\*", s, re.S).group(1).strip()
    code=re.search(r"\*\*Minimal code sample\*\*.*?```python\n(.*?)```", s, re.S).group(1)
    tb=re.search(r"\*\*Error output\*\*\s*(.*?)\*\*Versions\*\*", s, re.S).group(1).strip()
    tb=re.sub(r"^```\w*\n|\n```$", "", tb.strip()).strip()
    ver=s[s.index("**Versions**")+len("**Versions**"):].strip()
    return t, foot(desc), code, tb, ver
def pr_sections(s):
    out=[]
    for m in re.finditer(r"^## (PR \d+[^\n]*)\n(.*?)(?=^## |\Z)", s, re.S|re.M):
        sec=m.group(2); tm=re.search(r"^\*\*Title:\*\*\s*(.+)$", sec, re.M)
        if not tm: continue
        out.append((tm.group(1).strip(), foot(sec[tm.end():].strip())))
    return out
