# ---- round 2: fixed kit format (Title: line; ### PR n — `branch` — "title")
def r2_issue(path):
    s=read(path); m=re.search(r"^Title:\s*(.+)$", s, re.M); t=m.group(1).strip()
    body=foot(strip_comment(s[m.end():]))
    cm=re.search(r"[\(\[]\s*comment (?:on|for) (#\d+(?:\s*/\s*#\d+)*)\s*[\)\]]", t, re.I)
    existing=None
    if cm:
        existing=int(re.search(r"#(\d+)", cm.group(1)).group(1))
        t=(t[:cm.start()]+t[cm.end():]).strip().rstrip(" :—")
    return t, body, existing
def r2_prs(path):
    s=read(path); out=[]
    for m in re.finditer(r'^### PR (\d+) — `([^`]+)` — "(.+?)"\s*\n(.*?)(?=^### PR |\Z)', s, re.S|re.M):
        out.append(dict(n=int(m.group(1)), branch=m.group(2), title=m.group(3).strip(), body=foot(m.group(4).strip())))
    return out
def r2(key, owner, repo, base, template, guide, issue_files, pr_needs, order_note="", dir=None, no_prs=False, forked=False):
    key_dir = dir or key
    issues=[]
    for f in issue_files:
        iid=re.search(r"(?:issue|comment)-([a-z]+\d+)-", f).group(1).upper()
        t,b,ex=r2_issue(A+f"{key_dir}/upstream/{f}")
        d=dict(id=iid, title=t, body=b)
        if ex: d["existing"]=ex
        issues.append(d)
    prs=[]
    import os as _os
    for p,needs in zip(r2_prs(A+f"{key_dir}/upstream/pr-bodies.md") if (not no_prs and _os.path.exists(A+f"{key_dir}/upstream/pr-bodies.md")) else [], pr_needs):
        d=dict(id=needs, title=p["title"], body=p["body"], branch=p["branch"], needs=needs)
        ex=next((i.get("existing") for i in issues if i["id"]==needs), None)
        if ex: d["existing"]=ex
        prs.append(d)
    assert len(prs)==len(pr_needs), (key, len(prs), pr_needs)
    repos[key]=dict(owner=owner, repo=repo, fork=f"cindykrafft/{repo}", forked=forked, base=base, template=template, guide=guide, issues=issues, prs=prs, order_note=order_note)
